import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import api from "../api";
import Card from 'react-bootstrap/Card';
import ListGroup from 'react-bootstrap/ListGroup';

const BookPage = () => {
  const { id } = useParams();
  const [book, setBook] = useState(null);
  const [chapters, setChapters] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchBookDetails = async () => {
      try {
        const b_response = await api.get(`/api/books/${id}`);
        const c_response = await api.get(`/api/books/${id}/chapters`);
        setBook(b_response.data);
        setChapters(c_response.data.chapters);
      } catch (err) {
        console.error("Error fetching book details:", err);
        setError("Could not fetch book details.");
      }
    };
    fetchBookDetails();
  }, [id]);

  if (error) return <div>{error}</div>;
  if (!book) return <div>Loading...</div>;
  return (
    <Card style={{width:"500px", height:"600px"}}>
      <Card.Img variant="top" src={`http://127.0.0.1:5000/uploads/${book.image_filename}`} />
      <Card.Body>
        <Card.Title>{book.title}</Card.Title>
        <Card.Text>
        {book.content}
        </Card.Text>
      </Card.Body>
      <ListGroup className="list-group-flush">
      {chapters.map((chapter) => (
        <ListGroup.Item>Chapter {chapter.id}, {chapter.title}</ListGroup.Item>
      ))}
      </ListGroup>
      <Card.Body>Author: {book.author.username}</Card.Body>
    </Card>
  );
};

export default BookPage;
